// Sinh custom list, custom record, role (src/Objects) và bảng tra Schema.js (lớp api) từ tools/schema.mjs.
// Cách dùng: npm run gen:objects. File sinh ra có dòng "Generated by tools/gen_objects.mjs"; sửa schema rồi chạy lại.
import fs from "fs/promises";
import path from "path";
import { lists, records, roles } from "./schema.mjs";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "..");
const OBJ = path.join(ROOT, "src", "Objects");
const API = path.join(ROOT, "src", "FileCabinet", "SuiteScripts", "com.s4.vnpayroll", "api");

const SELECT = { employee: "-4", subsidiary: "-117", account: "-112", vendor: "-3", department: "-102", class: "-101", location: "-103", transaction: "-30", project: "-7" };
const TYPES = { text: "TEXT", textarea: "TEXTAREA", clob: "CLOBTEXT", int: "INTEGER", float: "FLOAT", currency: "CURRENCY", percent: "PERCENT", date: "DATE", check: "CHECKBOX" };

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const listId = (id) => `customlist_s4vp_${id}`;
const recId = (id) => `customrecord_s4vp_${id}`;
const fieldId = (rec, f) => `custrecord_s4vp_${rec.prefix}_${f}`;
const valId = (list, code) => `val_s4vp_${list}_${code.toLowerCase()}`;
function check(id, max) {
	if (id.length > max) throw new Error(`${id} longer than ${max} characters`);
	return id;
}

function listXml(id, [name, values]) {
	const vals = Object.entries(values)
		.map(([code, label]) => `    <customvalue scriptid="${valId(id, code)}">\n      <value>${esc(label)}</value>\n      <isinactive>F</isinactive>\n    </customvalue>`)
		.join("\n");
	check(listId(id), 38);
	Object.keys(values).forEach((c) => check(valId(id, c), 40));
	return `<customlist scriptid="${listId(id)}">\n  <name>S4VP ${id}</name>\n  <description>S4 VN Payroll code list ${id}; values keep the Acumatica codes (${Object.keys(values).join(", ")}).</description>\n  <isinactive>F</isinactive>\n  <isordered>T</isordered>\n  <customvalues>\n${vals}\n  </customvalues>\n</customlist>\n`;
}

function selectType(target) {
	if (target.startsWith("list:")) return `[${listId(target.slice(5))}]`;
	if (target.startsWith("rec:")) return `[${recId(target.slice(4))}]`;
	if (!SELECT[target]) throw new Error(`Unknown select target ${target}`);
	return SELECT[target];
}

function fieldXml(rec, [id, label, type, opt = {}]) {
	const lines = [`    <customrecordcustomfield scriptid="${check(fieldId(rec, id), 40)}">`, `      <label>${esc(label)}</label>`];
	if (type.startsWith("select:")) {
		lines.push("      <fieldtype>SELECT</fieldtype>", `      <selectrecordtype>${selectType(type.slice(7))}</selectrecordtype>`);
	} else if (type.startsWith("multi:")) {
		lines.push("      <fieldtype>MULTISELECT</fieldtype>", `      <selectrecordtype>${selectType(type.slice(6))}</selectrecordtype>`);
	} else {
		if (!TYPES[type]) throw new Error(`Unknown type ${type} on ${rec.id}.${id}`);
		lines.push(`      <fieldtype>${TYPES[type]}</fieldtype>`);
	}
	const help = opt.help || label;
	lines.push(
		`      <description>${esc(help)}</description>`,
		`      <help>${esc(help)}</help>`,
		`      <ismandatory>${opt.req ? "T" : "F"}</ismandatory>`,
		"      <storevalue>T</storevalue>",
		`      <displaytype>${opt.display || "NORMAL"}</displaytype>`,
		`      <isparent>${opt.parent ? "T" : "F"}</isparent>`,
		`      <showinlist>${opt.show === false || type === "clob" ? "F" : "T"}</showinlist>`
	);
	if (type === "check") lines.push(`      <defaultchecked>${opt.def === "T" ? "T" : "F"}</defaultchecked>`);
	lines.push("    </customrecordcustomfield>");
	return lines.join("\n");
}

function recordXml(rec) {
	const numbering = rec.numbering
		? `  <enablenumbering>T</enablenumbering>\n  <numberingprefix>${rec.numbering}</numberingprefix>\n  <numberingmindigits>6</numberingmindigits>\n  <numberinginit>1</numberinginit>\n`
		: "  <enablenumbering>F</enablenumbering>\n";
	const perms = Object.entries(rec.perms)
		.map(([role, level]) => `    <permission>\n      <permittedlevel>${level}</permittedlevel>\n      <permittedrole>[${role}]</permittedrole>\n    </permission>`)
		.join("\n");
	return `<customrecordtype scriptid="${recId(rec.id)}">
  <recordname>S4VP ${esc(rec.name)}</recordname>
  <description>${esc(rec.desc)} Acumatica screen ${rec.screen}. Generated by tools/gen_objects.mjs.</description>
  <accesstype>CUSTRECORDENTRYPERM</accesstype>
  <allowattachments>T</allowattachments>
  <allowinlinedeleting>${rec.child ? "T" : "F"}</allowinlinedeleting>
  <allowinlineediting>${rec.child ? "T" : "F"}</allowinlineediting>
  <allowquicksearch>F</allowquicksearch>
  <allowuiaccess>T</allowuiaccess>
  <enablekeywords>F</enablekeywords>
${numbering}  <enableoptimisticlocking>T</enableoptimisticlocking>
  <enablesystemnotes>T</enablesystemnotes>
  <hierarchical>F</hierarchical>
  <includename>${rec.includeName ? "T" : "F"}</includename>
  <isinactive>F</isinactive>
  <isordered>F</isordered>
  <showcreationdate>T</showcreationdate>
  <showlastmodified>T</showlastmodified>
  <showowner>F</showowner>
  <shownotes>T</shownotes>
  <customrecordcustomfields>
${rec.fields.map((f) => fieldXml(rec, f)).join("\n")}
  </customrecordcustomfields>
  <permissions>
${perms}
  </permissions>
</customrecordtype>
`;
}

function roleXml(role) {
	// Quyền custom record khai ở cả hai phía (record và role), nếu không SDF báo lỗi tham chiếu một chiều
	const recPerms = records.filter((r) => r.perms[role.id]).map((r) => [`[${recId(r.id)}]`, r.perms[role.id]]);
	const perms = role.perms.concat(recPerms).map(([key, level]) => `    <permission>\n      <permkey>${key}</permkey>\n      <permlevel>${level}</permlevel>\n    </permission>`).join("\n");
	return `<role scriptid="${role.id}">\n  <name>${esc(role.name)}</name>\n  <centertype>ACCOUNTCENTER</centertype>\n  <issalesrole>F</issalesrole>\n  <issupportrole>F</issupportrole>\n  <restricttimeandexpenses>F</restricttimeandexpenses>\n  <subsidiaryoption>ALL</subsidiaryoption>\n  <permissions>\n${perms}\n  </permissions>\n</role>\n`;
}

// Bảng tra cho lớp api: tên logic -> script id; list -> {mã: scriptid giá trị}
function schemaJs() {
	const recs = {};
	for (const r of records) {
		const fields = {};
		for (const [id, , type] of r.fields) fields[id] = { id: fieldId(r, id), type: type.split(":")[0], target: type.includes(":") ? type.slice(type.indexOf(":") + 1) : null };
		recs[r.id] = { type: recId(r.id), includeName: !!r.includeName, numbering: r.numbering || null, fields };
	}
	const ls = {};
	for (const [id, [, values]] of Object.entries(lists)) {
		ls[id] = { type: listId(id), values: Object.fromEntries(Object.keys(values).map((c) => [c, valId(id, c)])) };
	}
	return `/**
 * Bảng tra record, trường, custom list của S4 VN Payroll. Generated by tools/gen_objects.mjs from tools/schema.mjs. Do not edit.
 *
 * @NApiVersion 2.1
 * @NModuleScope SameAccount
 */
define([], () => {
	const records = ${JSON.stringify(recs, null, "\t").replace(/\n/g, "\n\t")};
	const lists = ${JSON.stringify(ls, null, "\t").replace(/\n/g, "\n\t")};
	return { records, lists };
});
`;
}

await fs.mkdir(OBJ, { recursive: true });
let n = 0;
for (const [id, def] of Object.entries(lists)) {
	await fs.writeFile(path.join(OBJ, `${listId(id)}.xml`), listXml(id, def));
	n++;
}
for (const rec of records) {
	await fs.writeFile(path.join(OBJ, `${recId(rec.id)}.xml`), recordXml(rec));
	n++;
}
for (const role of roles) {
	await fs.writeFile(path.join(OBJ, `${role.id}.xml`), roleXml(role));
	n++;
}
await fs.mkdir(API, { recursive: true });
await fs.writeFile(path.join(API, "Schema.js"), schemaJs());
console.log(`generated ${n} objects and api/Schema.js`);
